    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (3,1,'vehicle-maintenance','multiple_choice','How often should you check your engine oil level?','["Monthly","Weekly","Daily","Every 6 months"]',1,'Check engine oil weekly. Low oil can cause severe engine damage.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','What colour should engine oil be on the dipstick?','["Black always","Golden/amber to dark brown","Green","Red"]',1,'Fresh oil is golden/amber. Dark brown is normal with age. Milky means coolant leak.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','When should you change your engine oil?','["Every 3,000 km","Every 5,000-10,000 km or as recommended","Every 20,000 km","Once a year only"]',1,'Change oil every 5,000-10,000 km or as per manufacturer recommendation.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the check engine light indicate?','["Nothing serious","A problem with the engine or emissions system","Time for service","Low fuel"]',1,'Check engine light indicates a problem with the engine or emissions system. Get it checked.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the oil pressure warning light mean?','["Low oil level","Low oil pressure — stop immediately","Time for oil change","Normal operation"]',1,'Low oil pressure. Stop the engine immediately to avoid catastrophic damage.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the temperature warning light indicate?','["Low fuel","Engine overheating","Normal operation","Air conditioning on"]',1,'Engine is overheating. Stop safely and turn off the engine.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the battery warning light mean while driving?','["Battery is fine","Charging system problem","Battery needs replacement","Normal operation"]',1,'Battery light while driving means the charging system has a problem. Get it checked.',1,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the ABS warning light indicate?','["Brake pads worn","Anti-lock braking system problem","Normal operation","Handbrake on"]',1,'ABS system problem. Normal brakes still work but anti-lock may not.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the airbag warning light mean?','["Airbag deployed","Airbag system fault","Normal operation","Passenger airbag off"]',1,'Airbag system fault. Get it checked — airbags may not deploy in an accident.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does the tyre pressure warning light indicate?','["Tyres are fine","Low tyre pressure in one or more tyres","Time to rotate tyres","Normal operation"]',1,'Low tyre pressure. Check and inflate tyres to recommended pressure.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','How often should you change the air filter?','["Every 10,000 km","Every 15,000-30,000 km","Every 50,000 km","Never"]',1,'Change air filter every 15,000-30,000 km depending on driving conditions.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does a squealing noise when starting the engine indicate?','["Normal operation","Loose or worn fan/alternator belt","Low fuel","Engine damage"]',1,'Squealing on startup usually means a loose or worn belt. Get it checked.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does blue smoke from the exhaust mean?','["Normal operation","Burning oil — possible engine wear","Coolant leak","Rich fuel mixture"]',1,'Blue smoke means the engine is burning oil. Possible worn piston rings or valve seals.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does white smoke from the exhaust mean?','["Normal operation","Coolant leaking into engine","Burning oil","Rich mixture"]',1,'White smoke (not just condensation) may indicate coolant leaking into the engine.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does black smoke from the exhaust mean?','["Normal operation","Excessive fuel burning","Burning oil","Coolant leak"]',1,'Black smoke means too much fuel is being burned. Possible injector or filter problem.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','How often should you replace the fuel filter?','["Every 10,000 km","Every 20,000-40,000 km","Every 80,000 km","Never"]',1,'Replace fuel filter every 20,000-40,000 km for optimal engine performance.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does a grinding noise when braking indicate?','["Normal operation","Brake pads completely worn — metal on metal","New brakes bedding in","Loose wheel"]',1,'Grinding means brake pads are completely worn. Stop driving and replace immediately.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does a clicking noise when turning indicate?','["Normal operation","Possible CV joint problem","Low tyre pressure","Loose belt"]',1,'Clicking when turning often indicates a worn CV joint. Get it inspected.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does a humming noise that increases with speed indicate?','["Normal operation","Possible wheel bearing wear","Engine problem","Aerodynamic noise"]',1,'Humming that increases with speed often means a worn wheel bearing.',2,true),
    (3,1,'vehicle-maintenance','multiple_choice','What does a vibration in the steering wheel at high speed indicate?','["Normal operation","Wheel balancing or alignment issue","Engine problem","Brake problem"]',1,'Steering vibration at high speed usually means wheel balancing or alignment issue.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','How often should you service your vehicle?','["Every 3,000 km","Every 5,000-10,000 km","Every 20,000 km","Once a year only"]',1,'Service every 5,000-10,000 km or every 6 months, whichever comes first.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What is checked during a basic service?','["Only oil","Oil, filters, brakes, tyres, fluids","Only tyres","Only brakes"]',1,'Basic service includes oil change, filter checks, brake inspection, tyre check, fluid levels.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What fluids should be checked regularly?','["Only engine oil","Engine oil, coolant, brake fluid, power steering, transmission","Only coolant","Only brake fluid"]',1,'Check all fluids: engine oil, coolant, brake fluid, power steering, transmission.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does low coolant level cause?','["Better performance","Engine overheating","Improved fuel economy","Nothing"]',1,'Low coolant causes engine overheating which can lead to serious engine damage.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','When should you top up coolant?','["When the engine is hot","When the engine is cold","Never — it is sealed","Only at service"]',1,'Only top up coolant when the engine is cold to avoid burns from pressurised system.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What colour is coolant usually?','["Clear","Green, red, or blue","Black","Yellow only"]',1,'Coolant is typically green, red, or blue depending on the type. Never mix colours.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does low brake fluid indicate?','["Normal","Possible brake pad wear or leak","Too much braking","Nothing serious"]',1,'Low brake fluid may indicate worn brake pads or a leak. Check immediately.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a spongy brake pedal indicate?','["Normal","Air in brake lines","Worn pads","New brakes"]',1,'Spongy brake pedal means air in the brake lines. Bleed the brake system.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a hard brake pedal indicate?','["Normal","Possible brake booster failure","Worn pads","Too much fluid"]',1,'Hard brake pedal may indicate brake booster failure. Get it checked.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','How often should brake fluid be changed?','["Never","Every 2-3 years","Every 5 years","Every 10 years"]',1,'Brake fluid absorbs moisture. Change every 2-3 years for safety.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does power steering fluid do?','["Lubricates engine","Assists steering","Cools the engine","Brakes"]',1,'Power steering fluid assists with steering. Low fluid makes steering heavy.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What happens if power steering fluid is low?','["Steering becomes heavy","Engine stalls","Brakes fail","Nothing"]',0,'Low power steering fluid makes steering heavy and difficult.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does the alternator do?','["Starts the engine","Charges the battery while engine runs","Powers the radio only","Cools the engine"]',1,'The alternator charges the battery and powers electrical systems while the engine runs.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a failing alternator cause?','["Better performance","Battery drains and electrical failures","Improved fuel economy","Nothing"]',1,'Failing alternator causes battery drain and electrical system failures.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','How long does a car battery typically last?','["1 year","2-5 years","10 years","Lifetime"]',1,'Car batteries typically last 2-5 years depending on usage and climate.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What causes a battery to die quickly?','["Leaving lights on","Short trips only","Old battery","All of the above"]',3,'All of these can cause battery drain. Leaving lights on is most common.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a slow engine crank indicate?','["Normal","Weak battery or starter motor","Low fuel","Cold weather only"]',1,'Slow cranking usually means a weak battery or failing starter motor.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a clicking sound when turning the key indicate?','["Normal","Weak battery or bad starter","Low fuel","Engine flooded"]',1,'Clicking when starting usually means a weak battery or faulty starter solenoid.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What should you do if the engine overheats?','["Keep driving","Stop safely, turn off engine, do not open radiator cap","Open radiator cap immediately","Add cold water"]',1,'Stop safely, turn off engine. Never open the radiator cap when hot — pressurised steam.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What is the purpose of the radiator?','["Cool the engine","Heat the cabin","Start the engine","Charge battery"]',0,'The radiator cools the engine by dissipating heat from the coolant.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a coolant leak under the car look like?','["Black puddle","Green, red, or blue puddle","Clear puddle","Brown puddle"]',1,'Coolant leaks are usually green, red, or blue sweet-smelling puddles under the engine.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does an oil leak look like?','["Clear puddle","Black or dark brown puddle","Green puddle","Red puddle"]',1,'Oil leaks are black or dark brown puddles under the engine.',1,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a transmission fluid leak look like?','["Clear puddle","Red or brown puddle near middle of car","Green puddle","Black puddle"]',1,'Transmission fluid is red or reddish-brown, found near the middle of the car.',2,true),
    (3,2,'vehicle-maintenance','multiple_choice','What does a brake fluid leak look like?','["Clear or light brown puddle near wheels","Green puddle","Black puddle","Red puddle"]',0,'Brake fluid is clear or light brown, found near wheels. Very dangerous — get fixed immediately.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is the minimum legal tyre tread depth in Nigeria?','["1.0 mm","1.6 mm","2.0 mm","3.0 mm"]',1,'Minimum legal tread depth is 1.6mm. Below this is an offence.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','How can you check tyre tread depth?','["Use a coin","Use a tread depth gauge or the wear indicator bars","Look at the colour","Ask a mechanic"]',1,'Use a tread depth gauge or check the wear indicator bars in the tyre grooves.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is the correct tyre pressure found?','["On the tyre only","In the vehicle manual or door jamb sticker","On the dashboard","Guess"]',1,'Find correct tyre pressure in the vehicle manual or on the sticker inside the door jamb.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What happens with overinflated tyres?','["Better grip","Reduced contact area, poor grip, uneven wear","No effect","Better fuel economy"]',1,'Overinflation reduces contact area, causing poor grip and uneven centre wear.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What happens with underinflated tyres?','["Better grip","Increased fuel consumption, poor handling, overheating","No effect","Better comfort only"]',1,'Underinflation increases fuel consumption, causes poor handling and tyre overheating.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','How often should you rotate your tyres?','["Every 5,000 km","Every 10,000 km","Every 20,000 km","Never"]',1,'Rotate tyres every 10,000 km for even wear.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is a spare tyre for?','["Long-term use","Temporary emergency use only","Permanent replacement","Decoration"]',1,'Spare tyres (especially space-savers) are for temporary emergency use only. Replace the main tyre.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is the speed limit when using a space-saver spare tyre?','["Normal speed","80 km/h maximum","50 km/h","No limit"]',1,'Space-saver spare tyres are limited to 80 km/h maximum.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does uneven tyre wear on one side indicate?','["Normal","Wheel alignment problem","Overinflation","Underinflation"]',1,'Uneven wear on one side usually indicates a wheel alignment or suspension problem.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a bulge or bubble on a tyre sidewall mean?','["Normal","Tyre damage — replace immediately","Low pressure","Needs rotation"]',1,'A bulge means the tyre structure is damaged. Replace immediately — risk of blowout.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a cut in the tyre sidewall mean?','["Normal","Tyre damage — have it inspected","Low pressure","Needs air"]',1,'A cut in the sidewall is dangerous. Have it inspected by a professional.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is the purpose of wheel balancing?','["Better fuel economy","Prevent vibration and uneven tyre wear","Better braking","Better steering"]',1,'Wheel balancing prevents vibration at speed and ensures even tyre wear.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is the purpose of wheel alignment?','["Better looks","Ensure wheels are parallel for straight tracking","Better fuel economy","Better braking"]',1,'Alignment ensures wheels are parallel and the car tracks straight without pulling.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a car pulling to one side indicate?','["Normal","Possible alignment or tyre pressure issue","Engine problem","Brake problem"]',1,'Pulling to one side may indicate alignment issues or uneven tyre pressure.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What is the purpose of shock absorbers?','["Comfort only","Control spring oscillation for safety and comfort","Better fuel economy","Better braking"]',1,'Shock absorbers control spring movement, keeping tyres in contact with the road.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a bouncy ride indicate?','["Normal","Worn shock absorbers","Overinflated tyres","New shocks"]',1,'A bouncy ride means worn shock absorbers. Replace for safety.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does excessive body roll in corners indicate?','["Normal","Worn shock absorbers or suspension","Overinflated tyres","Low fuel"]',1,'Excessive body roll may indicate worn shock absorbers or suspension components.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a clunking noise over bumps indicate?','["Normal","Worn suspension components","Engine problem","Brake problem"]',1,'Clunking over bumps usually means worn suspension bushes or joints.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does uneven brake pad wear indicate?','["Normal","Stuck caliper or alignment issue","New brakes","Overheating"]',1,'Uneven pad wear may indicate a stuck caliper. Get it checked.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','How long do brake pads typically last?','["10,000 km","30,000-70,000 km","100,000 km","Lifetime"]',1,'Brake pads typically last 30,000-70,000 km depending on driving style.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a brake pedal that goes to the floor indicate?','["Normal","Brake fluid leak or master cylinder failure","Worn pads","New brakes"]',1,'Brake pedal to the floor is a serious problem. Stop immediately — brake failure.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does the handbrake not holding indicate?','["Normal","Worn handbrake cable or rear brake adjustment","Front brake problem","Nothing serious"]',1,'Handbrake not holding means worn cable or rear brakes need adjustment.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','How often should you check your lights?','["Monthly","Weekly","Daily","Every 6 months"]',1,'Check all lights weekly. Faulty lights are an offence and safety risk.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What should you do if a headlight is not working?','["Drive carefully","Replace immediately","Only at service","Use high beam only"]',1,'Replace immediately. Driving without headlights is an offence and dangerous.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a flickering headlight indicate?','["Normal","Loose connection or failing alternator","New bulb needed","Battery fine"]',1,'Flickering may indicate a loose connection or failing alternator.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a horn that does not work indicate?','["Normal","Faulty horn, fuse, or wiring","Battery problem","Engine problem"]',1,'Non-working horn may be a blown fuse, faulty horn, or wiring issue.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a cracked wing mirror indicate?','["Normal","Needs replacement for safety and legality","Nothing serious","Only cosmetic"]',1,'A cracked mirror reduces visibility. Replace for safety and legal compliance.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a wiper that leaves streaks indicate?','["Normal","Worn wiper blades","Low washer fluid","Wrong wipers"]',1,'Streaking wipers are worn. Replace for clear visibility in rain.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','How often should wiper blades be replaced?','["Every 6 months","Every 6-12 months","Every 2 years","Never"]',1,'Replace wiper blades every 6-12 months for optimal performance.',1,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does washer fluid not spraying indicate?','["Normal","Blocked nozzle or empty reservoir","Pump failure only","Fuse only"]',1,'Usually a blocked nozzle or empty reservoir. Check and refill.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a burning smell from the engine indicate?','["Normal","Oil or fluid leak onto hot engine","New car smell","Fuel"]',1,'Burning smell may indicate oil or fluid leaking onto a hot engine. Check immediately.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a sweet smell inside the car indicate?','["Normal","Coolant leak in the cabin","Fuel leak","New car smell"]',1,'A sweet smell may indicate a coolant leak from the heater core. Get it checked.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a fuel smell inside the car indicate?','["Normal","Fuel leak — dangerous","Nothing serious","Air freshener"]',1,'Fuel smell inside the car is dangerous. Check for leaks immediately.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a rotten egg smell indicate?','["Normal","Catalytic converter or fuel system problem","Fuel leak","Coolant leak"]',1,'Rotten egg smell often indicates a catalytic converter or fuel mixture problem.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a musty smell from the AC indicate?','["Normal","Mould in AC system","Fuel leak","Coolant leak"]',1,'Musty AC smell indicates mould in the system. Service the AC.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does AC that blows warm air indicate?','["Normal","Low refrigerant or AC system problem","Engine overheating","Nothing serious"]',1,'Warm AC means low refrigerant or a system problem. Get it serviced.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a squealing noise when the AC is on indicate?','["Normal","AC belt loose or worn","Engine problem","Normal AC operation"]',1,'Squealing with AC on usually means a loose or worn AC belt.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a rattling noise from under the car indicate?','["Normal","Loose exhaust or heat shield","Engine problem","Tyre problem"]',1,'Rattling underneath often means a loose exhaust or heat shield.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a loud exhaust indicate?','["Normal","Exhaust leak or hole in exhaust system","Engine problem","Normal for old cars"]',1,'A loud exhaust means a leak or hole. Get it repaired for safety and noise regulations.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a clunking noise when shifting gears indicate?','["Normal","Possible transmission mount or U-joint problem","Engine problem","Brake problem"]',1,'Clunking when shifting may indicate worn transmission mounts or U-joints.',3,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does difficulty shifting gears indicate?','["Normal","Clutch or transmission problem","Engine problem","Brake problem"]',1,'Difficulty shifting may indicate a clutch or transmission problem.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a slipping clutch indicate?','["Normal","Clutch disc worn — needs replacement","Engine problem","Transmission fluid"]',1,'A slipping clutch (engine revs but speed does not increase) means the clutch is worn.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a burning rubber smell indicate?','["Normal","Belt slipping or rubbing on a pulley","Fuel leak","Coolant leak"]',1,'Burning rubber smell often means a belt is slipping or rubbing.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a whining noise from the engine indicate?','["Normal","Possible power steering or alternator problem","Tyre problem","Brake problem"]',1,'Whining from the engine may indicate power steering or alternator issues.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a knocking noise from the engine indicate?','["Normal","Serious engine problem — stop driving","Fuel problem","Exhaust problem"]',1,'Engine knocking is serious. Stop driving immediately to avoid engine failure.',3,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does poor fuel economy indicate?','["Normal","Possible dirty air filter, low tyre pressure, or engine issue","Nothing","AC use"]',1,'Poor fuel economy may mean dirty air filter, low tyre pressure, or engine issue.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a rough idle indicate?','["Normal","Possible spark plug, air filter, or fuel system issue","Nothing serious","AC on"]',1,'Rough idle may indicate spark plug, air filter, or fuel system problems.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does stalling at traffic lights indicate?','["Normal","Possible idle control valve or fuel system problem","Nothing serious","Low fuel"]',1,'Stalling may indicate an idle control valve or fuel system problem.',2,true),
    (3,3,'vehicle-maintenance','multiple_choice','What does a car that cranks but does not start indicate?','["Normal","Fuel or ignition problem","Battery fine","Nothing serious"]',1,'Cranks but no start usually means fuel or ignition system problem.',2,true);
